func (stream *Stream) RecvSubscribe(ctx context.Context) (SubscribeEvent, error) {
	event, err := stream.Recv(ctx)
	if err != nil {
		return nil, err
	}
	typed, ok := event.(SubscribeEvent)
	if !ok {
		return nil, fmt.Errorf("%w: %s is not a subscribe event", ErrDecode, event.EventName())
	}
	return typed, nil
}

